//! The implementation file of a component: everything that calls into the
//! scaffolding.

use std::fmt::Write;

use super::names::{class, fill, var};
use super::types::Gen;

impl Gen<'_> {
    pub(crate) fn emit_source(&self, header_name: &str) -> String {
        let ns = &self.ns;
        let mut out = String::new();
        let _ = writeln!(
            out,
            "// This file was autogenerated by uniffi-bindgen-cpp. Do not edit it by hand.\n"
        );
        let _ = writeln!(out, "#include \"{header_name}\"\n");
        out.push_str(&self.emit_ffi_declarations());
        let _ = writeln!(out, "namespace {ns} {{\n");
        let _ = writeln!(out, "namespace ffi = ::{};\n", self.ffi_ns());
        out.push_str(&self.emit_helpers());

        // Everything private to this file.
        let _ = writeln!(out, "namespace {{\n");
        out.push_str(super::callbacks::FOREIGN_FUTURE_DROPPED);
        for cb in self.ci.callback_interface_definitions() {
            out.push_str(&self.emit_handle_map(&class(cb.name())));
        }
        for obj in self.ci.object_definitions() {
            if obj.has_callback_interface() {
                out.push_str(&self.emit_handle_map(&class(obj.name())));
            }
        }
        for obj in self.ci.object_definitions() {
            if obj.is_trait_interface() || obj.has_callback_interface() {
                out.push_str(&self.emit_rust_impl_class(obj));
            }
        }
        for cb in self.ci.callback_interface_definitions() {
            out.push_str(&self.emit_callback_vtable(
                &class(cb.name()),
                &cb.vtable_methods(),
                cb.ffi_init_callback().name(),
                &self.ffi_type(&cb.vtable()),
            ));
        }
        for obj in self.ci.object_definitions() {
            if obj.has_callback_interface()
                && let Some(vtable) = obj.vtable()
            {
                out.push_str(&self.emit_callback_vtable(
                    &class(obj.name()),
                    &obj.vtable_methods(),
                    obj.ffi_init_callback().name(),
                    &self.ffi_type(&vtable),
                ));
            }
        }
        let _ = writeln!(out, "}}  // namespace\n");

        out.push_str(&self.emit_ensure_init());

        let _ = writeln!(out, "namespace uniffi_detail {{\n");
        for obj in self.ci.object_definitions() {
            out.push_str(&self.emit_object_lift_lower(obj));
        }
        for cb in self.ci.callback_interface_definitions() {
            out.push_str(&self.emit_callback_lift_lower(&class(cb.name())));
        }
        for e in self.ci.enum_definitions() {
            if self.is_error_enum(e.name()) {
                let name = class(e.name());
                let _ = writeln!(
                    out,
                    "{}",
                    fill(
                        "[[noreturn]] void throw_buf_@name@(uniffi::RustBuffer buffer) {\n    BufferGuard guard{buffer};\n    uniffi::Reader reader(buffer.data, static_cast<size_t>(buffer.len));\n    uniffi::Codec<std::shared_ptr<::@ns@::@name@>>::read(reader)->uniffi_throw();\n    std::abort();  // not reached; GCC does not take [[noreturn]] from a virtual call\n}\n",
                        &[("name", &name), ("ns", ns)],
                    )
                );
            }
        }
        for obj in self.ci.object_definitions() {
            if self.is_error_object(obj.name()) {
                let name = class(obj.name());
                let thrown = if obj.is_trait_interface() || obj.has_callback_interface() {
                    format!("{name}RustImpl(handle)")
                } else {
                    format!("::{ns}::{name}(uniffi::HandleTag{{}}, handle)")
                };
                let _ = writeln!(
                    out,
                    "[[noreturn]] void throw_buf_{name}(uniffi::RustBuffer buffer) {{\n    BufferGuard guard{{buffer}};\n    uniffi::Reader reader(buffer.data, static_cast<size_t>(buffer.len));\n    uint64_t handle = reader.read_int<uint64_t>();\n    throw {thrown};\n}}\n"
                );
            }
        }
        let _ = writeln!(out, "}}  // namespace uniffi_detail\n");

        for obj in self.ci.object_definitions() {
            if !(obj.is_trait_interface() || obj.has_callback_interface()) {
                out.push_str(&self.emit_object_methods(obj));
            }
        }
        out.push_str(&self.value_member_definitions());
        for func in self.ci.function_definitions() {
            let _ = writeln!(
                out,
                "{} {{\n{}}}\n",
                self.signature(func, &var(func.name()), false),
                self.call_body(func, None, None, 4)
            );
        }
        let _ = writeln!(out, "}}  // namespace {ns}");
        out
    }

    /// Buffer plumbing and call-status handling.
    fn emit_helpers(&self) -> String {
        let from_bytes = self.ci.ffi_rustbuffer_from_bytes();
        let free = self.ci.ffi_rustbuffer_free();
        fill(
            r#"namespace uniffi_detail {

void ensure_init();

namespace {

/// Frees a Rust buffer when it goes out of scope.
struct BufferGuard {
    uniffi::RustBuffer buffer;
    ~BufferGuard() {
        uniffi::RustCallStatus status{};
        ffi::@free@(buffer, &status);
    }
};

[[maybe_unused]] uniffi::RustBuffer buffer_from_bytes(const uint8_t* data, size_t len) {
    uniffi::ForeignBytes bytes{static_cast<int32_t>(len), data};
    uniffi::RustCallStatus status{};
    uniffi::RustBuffer buffer = ffi::@from_bytes@(bytes, &status);
    if (status.code != uniffi::CALL_SUCCESS) {
        throw uniffi::InternalError("could not allocate a Rust buffer");
    }
    return buffer;
}

using Thrower = void (*)(uniffi::RustBuffer);

[[maybe_unused]] void check_status(uniffi::RustCallStatus& status, Thrower thrower = nullptr) {
    switch (status.code) {
        case uniffi::CALL_SUCCESS:
            return;
        case uniffi::CALL_ERROR:
            if (thrower != nullptr) {
                thrower(status.error_buf);
            }
            {
                BufferGuard guard{status.error_buf};
            }
            throw uniffi::InternalError("the call failed with an error the bindings do not expect");
        case uniffi::CALL_UNEXPECTED_ERROR: {
            std::string message = "Rust panic";
            BufferGuard guard{status.error_buf};
            if (status.error_buf.len > 0) {
                message.assign(reinterpret_cast<const char*>(status.error_buf.data),
                               static_cast<size_t>(status.error_buf.len));
            }
            throw uniffi::PanicError(message);
        }
        case uniffi::CALL_CANCELLED:
            throw uniffi::CancelledError();
        default:
            throw uniffi::InternalError("unexpected RustCallStatus code");
    }
}

template <class T>
uniffi::RustBuffer lower_buf(const T& value) {
    uniffi::Writer writer;
    uniffi::Codec<T>::write(writer, value);
    return buffer_from_bytes(writer.bytes().data(), writer.bytes().size());
}

template <class T>
T lift_buf(uniffi::RustBuffer buffer) {
    BufferGuard guard{buffer};
    uniffi::Reader reader(buffer.data, static_cast<size_t>(buffer.len));
    T value = uniffi::Codec<T>::read(reader);
    if (reader.has_remaining()) {
        throw uniffi::InternalError("the buffer still has data after lifting its containing value");
    }
    return value;
}

template <class E>
uniffi::RustBuffer lower_error(const E& error) {
    uniffi::Writer writer;
    uniffi::Codec<std::shared_ptr<E>>::write_value(writer, error);
    return buffer_from_bytes(writer.bytes().data(), writer.bytes().size());
}

[[maybe_unused]] uniffi::RustBuffer lower_string(std::string_view value) {
    return buffer_from_bytes(reinterpret_cast<const uint8_t*>(value.data()), value.size());
}

[[maybe_unused]] std::string lift_string(uniffi::RustBuffer buffer) {
    BufferGuard guard{buffer};
    return std::string(reinterpret_cast<const char*>(buffer.data), static_cast<size_t>(buffer.len));
}

}  // namespace
}  // namespace uniffi_detail

"#,
            &[("free", free.name()), ("from_bytes", from_bytes.name())],
        )
    }

    fn emit_ensure_init(&self) -> String {
        let contract = self.ci.ffi_uniffi_contract_version();
        let mut checks = String::new();
        if !self.config.omit_checksums {
            for (name, expected) in self.ci.iter_checksums() {
                let _ = writeln!(
                    checks,
                    "        if (ffi::{name}() != {expected}) {{\n            throw uniffi::InternalError(\"UniFFI API checksum mismatch: try cleaning and rebuilding your project\");\n        }}"
                );
            }
        }
        // Components this one uses register their callback interfaces first: C++ may pass
        // one of their traits to this component before calling into theirs.
        let mut inits: String = self
            .external_namespaces()
            .iter()
            .map(|ns| format!("        ::{ns}::uniffi_detail::ensure_init();\n"))
            .collect();
        for cb in self.ci.callback_interface_definitions() {
            let _ = writeln!(inits, "        init_{}();", class(cb.name()));
        }
        for obj in self.ci.object_definitions() {
            if obj.has_callback_interface() {
                let _ = writeln!(inits, "        init_{}();", class(obj.name()));
            }
        }
        format!(
            "namespace uniffi_detail {{\n\nvoid ensure_init() {{\n    static const bool initialized = [] {{\n        if (ffi::{contract}() != {version}) {{\n            throw uniffi::InternalError(\"UniFFI contract version mismatch: try cleaning and rebuilding your project\");\n        }}\n{checks}{inits}        return true;\n    }}();\n    (void)initialized;\n}}\n\n}}  // namespace uniffi_detail\n\n",
            contract = contract.name(),
            version = self.ci.uniffi_contract_version(),
        )
    }

    fn emit_handle_map(&self, name: &str) -> String {
        format!(
            "uniffi::HandleMap<std::shared_ptr<{name}>>& handle_map_{name}() {{\n    static auto* map = new uniffi::HandleMap<std::shared_ptr<{name}>>();\n    return *map;\n}}\n\n"
        )
    }
}
